package vn.edu.eaut.lab7.controller; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.*; @WebServlet("/login") public class LoginController extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/login.jsp").forward(r,s);} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String u=r.getParameter("username"),p=r.getParameter("password");if("admin".equals(u)&&"123456".equals(p)){r.getSession().setAttribute("user",u);r.getSession().setAttribute("role","admin");s.sendRedirect(r.getContextPath()+"/admin");}else{s.sendRedirect(r.getContextPath()+"/login?error=1");}}}